class MatchPhase(str, Enum):
    LOADING = "loading"  # match created, waiting for the human to finish loading
    PREPARATION = "preparation"  # preparation island countdown
    AIRCRAFT = "aircraft"  # plane flies its route, participants may jump
    PLAYING = "playing"  # everyone has left the plane
    ENDED = "ended"  # winner known, results shown
    CLOSED = "closed"  # results delivered, match may be removed


