@dataclass(frozen=True)
class Rect:
    """Axis-aligned box on the ground plane. Used for buildings, rocks and water."""

    min_x: float
    min_y: float
    max_x: float
    max_y: float

    def contains(self, x: float, y: float) -> bool:
        return self.min_x <= x <= self.max_x and self.min_y <= y <= self.max_y


