@dataclass
class SoloMatch:
    match_id: str
    config: SoloMatchConfig
    map: MapDefinition
    rng: random.Random
    phase: MatchPhase = MatchPhase.LOADING
    clock: float = 0.0  # seconds since creation
    tick: int = 0
    phase_started_at: float = 0.0
    phase_ends_at: float = 0.0
    participants: dict[str, Participant] = field(default_factory=dict)
    loot: dict[str, GroundLoot] = field(default_factory=dict)
    crates: dict[str, DeathCrate] = field(default_factory=dict)
    doors: dict[str, Door] = field(default_factory=dict)
    vehicles: dict[str, Vehicle] = field(default_factory=dict)
    aircraft: Aircraft | None = None
    zone: SafeZone = field(default_factory=SafeZone)
    events: list[MatchEvent] = field(default_factory=list)
    # Absolute sequence number of events[0]; grows as the engine trims delivered events.
    events_base: int = 0
    # Readers that still need events from an absolute position on (for example the bot driver).
    # The engine never trims past the lowest hold.
    event_holds: dict[str, int] = field(default_factory=dict)
    elimination_order: list[str] = field(default_factory=list)
    winner_id: str | None = None
    results: list[ParticipantResult] | None = None
    rewards_granted: bool = False
    started_playing_at: float | None = None
    _next_id: int = 0

    def new_id(self, prefix: str) -> str:
        self._next_id += 1
        return f"{prefix}-{self._next_id}"

    def emit(self, kind: str, **data) -> None:
        self.events.append(MatchEvent(kind=kind, at=self.clock, data=data))

    def alive(self) -> list[Participant]:
        return [p for p in self.participants.values() if p.alive]

    def humans(self) -> list[Participant]:
        return [p for p in self.participants.values() if not p.is_bot]
